private.reference_solution:
var firstTokens = (Console.ReadLine() ?? "").Split(' ', StringSplitOptions.RemoveEmptyEntries);
var secondTokens = (Console.ReadLine() ?? "").Split(' ', StringSplitOptions.RemoveEmptyEntries);
if (firstTokens.Length != 2 || secondTokens.Length != 2) Environment.Exit(1);
if (!int.TryParse(firstTokens[0], out var x1)) Environment.Exit(1);
if (!int.TryParse(firstTokens[1], out var y1)) Environment.Exit(1);
if (!int.TryParse(secondTokens[0], out var x2)) Environment.Exit(1);
if (!int.TryParse(secondTokens[1], out var y2)) Environment.Exit(1);
var from = new Point(x1, y1);
Console.WriteLine(from.DistanceTo(new Point(x2, y2)));

struct Point
{
    public int X;
    public int Y;

    public Point(int x, int y)
    {
        X = x;
        Y = y;
    }

    public long DistanceTo(Point other)
    {
        var dx = Math.Abs((long)X - other.X);
        var dy = Math.Abs((long)Y - other.Y);
        return dx + dy;
    }
}
